 "const cases={overwrite:['same path, changed bytes','IDENTITY','capture object version/content identity'],dupe:['two rows for order 42','CARDINALITY','rank to one source winner before MERGE'],repair:['one branch failed','RUN STATE','repair/retry failed branch with repeat-safe writes'],heavy:['one query is slow','PER-QUERY WORK','profile, then consider scale up'],queue:['twenty readers wait','CONCURRENCY','confirm queueing, then scale out'],share:['bad view still visible','PUBLICATION','remove/revoke the exposed certified object']};let shown=false;function paintRetrieval(){const [label,stage,fix]=cases[incident.value];retrievalWorld.innerHTML='<div class=\"row\"><div class=\"node fail\"><strong>symptom</strong><br>'+label+'</div><div class=arrow>→</div><div class=\"node '+(shown?'ok':'wait')+'\"><strong>'+(shown?stage:'predict first')+'</strong><br>'+(shown?fix:'Which mechanism changed?')+'</div></div><p><strong>Proof:</strong> '+(shown?({'overwrite':'version/content metadata differs','dupe':'count per key is one','repair':'failed task reran; successful task did not duplicate','heavy':'profile shows query work fell','queue':'queued time/concurrency improves','share':'grant/share listing no longer exposes object'}[incident.value]):'hidden until reveal')+'</p>';};incident.onchange=()=>{shown=false;paintRetrieval();};revealControl.onclick=()=>{shown=true;paintRetrieval();};paintRetrieval();",
